SELECT id, user_id AS userId, job_id AS jobId, resume_id AS resumeId,
       employer_id AS employerId, cover_letter AS coverLetter, status, deleted,
       create_time AS createTime, update_time AS updateTime
FROM t_applications
WHERE employer_id = #{employerId} AND deleted = 0
AND job_id = #{jobId}
AND status = #{status}
ORDER BY id DESC
LIMIT #{offset}, #{size}

